def allocate_wells(A, N):
    n = len(A)
    if N > n:
        return []
    best = None  # (diff, cuts)
    # 候选下界 L：所有环形子段和
    sums = sorted({sum(A[(s + i) % n] for i in range(l)) for s in range(n) for l in range(1, n + 1)})
    for s in range(n):                      # 第一刀切在 s 之前
        B = A[s:] + A[:s]
        pre = [0]
        for x in B:
            pre.append(pre[-1] + x)
        for L in sums:
            if L * N > pre[n]:
                break
            INF = float('inf')
            # dp[j][i]: 前 i 个分成 j 段、每段 >= L 时的最小最大段和
            dp = [[INF] * (n + 1) for _ in range(N + 1)]
            par = [[-1] * (n + 1) for _ in range(N + 1)]
            dp[0][0] = 0
            for j in range(1, N + 1):
                for i in range(j, n + 1):
                    for k in range(j - 1, i):
                        seg = pre[i] - pre[k]
                        if seg >= L and dp[j - 1][k] < INF:
                            v = max(dp[j - 1][k], seg)
                            if v < dp[j][i]:
                                dp[j][i], par[j][i] = v, k
            if dp[N][n] == INF:
                continue
            diff = dp[N][n] - L
            if best is None or diff < best[0]:
                cuts, i = [], n
                for j in range(N, 0, -1):
                    k = par[j][i]
                    cuts.append(((s + k) % n, i - k))
                    i = k
                best = (diff, cuts[::-1])
    # 输出顺序：从包含下标 0 的那段开始，顺着数组往后
    segs = best[1]
    def contains0(seg):
        st, ln = seg
        return st == 0 or st + ln > n
    idx = next(i for i, sg in enumerate(segs) if contains0(sg))
    segs = segs[idx:] + segs[:idx]
    return [sum(A[(st + t) % n] for t in range(ln)) for st, ln in segs]
